function deskSpark(vals,c){const n=vals.length;if(n<2)return '';const W=120,H=32,mn=Math.min(0,...vals),mx=Math.max(...vals,mn+1e-9);const y=v=>(H-2-(H-4)*(v-mn)/(mx-mn)).toFixed(1);
  const pts=vals.map((v,i)=>`${(W*i/(n-1)).toFixed(1)},${y(v)}`).join(' ');
  return `<svg class="dspark" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true">${mn<0?`<line x1="0" x2="${W}" y1="${y(0)}" y2="${y(0)}" stroke="var(--line)" stroke-dasharray="3 3" vector-effect="non-scaling-stroke"/>`:''}<polyline points="${pts}" fill="none" stroke="${c}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round" vector-effect="non-scaling-stroke"/></svg>`;}
const deskDelta=(a,b)=>a&&b!=null&&isFinite(b/a)&&a>0?`<span class="${b>=a?'pos':'neg'}">${b>=a?'▲':'▼'} ${pctN(Math.abs(Math.round((b/a-1)*100)))}</span>`:'';
