  if(G.hto&&G.hto.them)add('bad',(LANG_EN?`Hostile takeover attempt: ${(comp(G.hto.them.cid)||{}).name||"a rival"} is trying to acquire your company.`:`Düşmanca devralma girişimi: ${(comp(G.hto.them.cid)||{}).name||'bir rakip'} şirketini almaya çalışıyor.`),'fin:dusmanca');
