    <div class="pb"><div class="grid3">${SEGS.map(s=>`<div class="proj"><b>${s==='eco'?'Fiyat odaklı':s==='main'?'Ana akım':'Seçici (meraklı ve kurumsal)'}</b><div class="small muted">${SEG_D[s]}</div></div>`).join('')}</div></div>
